<section class="bl-related bl-shell" id="related-products" aria-labelledby="related-title"><div class="bl-small-section-heading"><div><p class="bl-eyebrow">EXPLORE YOUR OPTIONS</p><h2 id="related-title">MORE FROM THE RANGE.</h2></div><a class="bl-text-link" href="<?= bl_escape($familyUrl) ?>">View the range <?= bl_icon('arrow-up-right') ?></a></div>
  <?php if ($compareRows): ?><div class="bl-product-compare" role="region" aria-label="<?= bl_escape($product['model']) ?> compared with the models either side" tabindex="0"><table><caption><?= bl_escape($product['model']) ?> next to the models either side of it</caption><thead><tr><th scope="col"><span class="bl-visually-hidden">Specification</span></th><?php foreach ($neighbours as $model): ?><th scope="col"<?= $model['slug'] === $product['slug'] ? ' aria-current="true"' : '' ?>><?php if ($model['slug'] === $product['slug']): ?><?= bl_escape($model['model']) ?> <small>This model</small><?php else: ?><a href="<?= bl_escape(bl_product_url($model)) ?>"><?= bl_escape($model['model']) ?></a><?php endif; ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($compareRows as $label => $values): ?><tr><th scope="row"><?= bl_escape($label) ?></th><?php foreach ($values as $i => $value): ?><td<?= $neighbours[$i]['slug'] === $product['slug'] ? ' aria-current="true"' : '' ?>><?= bl_escape($value) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
  <div class="bl-product-grid"><?php $currentSlug = $product['slug']; $currentCategory = $product['category']; $compared = array_column($neighbours, 'slug'); $others = array_values(array_filter(bl_products(), static fn($p) => $p['slug'] !== $currentSlug && $p['category'] === $currentCategory)); /* models already in the table above are not shown twice */ $related = array_slice([...array_filter($others, static fn($p) => !in_array($p['slug'], $compared, true)), ...array_filter($others, static fn($p) => in_array($p['slug'], $compared, true))], 0, 3); foreach ($related as $relatedProduct) bl_product_card($relatedProduct, '', 'h3'); ?></div></section>
<dialog class="bl-lightbox" id="product-lightbox" aria-label="<?= bl_escape($product['model']) ?> photographs"><figure><img alt=""><figcaption><span data-lightbox-caption></span><small data-lightbox-count></small></figcaption></figure><button class="bl-lightbox-close bl-circle-button" type="button" data-lightbox-close aria-label="Close"><?= bl_icon('x') ?></button><button class="bl-lightbox-step bl-lightbox-prev bl-circle-button" type="button" data-lightbox-step="-1" aria-label="Previous photograph"><?= bl_icon('arrow-left') ?></button><button class="bl-lightbox-step bl-lightbox-next bl-circle-button" type="button" data-lightbox-step="1" aria-label="Next photograph"><?= bl_icon('arrow-left') ?></button></dialog>
